-- Parzellen nach Wunsch (Julian, 19. November: «mache ein extra Ordner bei
-- Aurora und nenne das Parzellen nach Wunsch, macht alle rein, die diese
-- Kriterien haben»). Ein Ordner ist eine feste Auswahl mit ihrem
-- Kriterium. Gerechnet auf dem Runner, nicht in der Datenbank (CLAUDE.md,
-- «Die Datenbank bedient die Seite»); hier steht nur das Ergebnis.
--
-- Der erste Ordner: Parzellen über 3000 m², mehrheitlich in der Bauzone,
-- in Sarnen (OW) und in Stans, Stansstad, Hergiswil, Ennetbürgen und
-- Buochs (NW). Obwalden und Nidwalden geben die amtliche Fläche nicht frei
-- ab (geodienste.ch: Freigabe nötig); sie ist aus dem Umriss der
-- Vermessung beim Bund gerechnet (an einer Zürcher Parzelle 2185 statt
-- 2187 m²). Baurechte zählen nicht, sonst stünde dieselbe Fläche doppelt.
-- Je Gemeinde ergeben alle Parzellen zusammen die Gemeindefläche des
-- Bundes, es fehlt also keine. Die Zone ist die harmonisierte des Bundes
-- (Bauzonen Schweiz), je Parzelle die mit dem grössten Anteil.
--
-- Nur Lesen für Angemeldete; geschrieben wird mit Migrationen.

create table if not exists public.wunsch_ordner (
  id          uuid primary key default gen_random_uuid(),
  name        text not null unique check (length(trim(name)) between 1 and 120),
  kriterium   text not null,
  quelle      text not null,
  stand       text not null,
  erstellt_am timestamptz not null default now()
);

create table if not exists public.wunsch_parzelle (
  ordner_id      uuid not null references public.wunsch_ordner(id) on delete cascade,
  egrid          text not null check (egrid ~ '^CH[0-9]{12}$'),
  kanton         text not null,
  bfs            integer not null,
  gemeinde       text not null,
  nummer         text not null,
  flaeche        integer not null check (flaeche > 0),
  zone           text not null,
  bauzone_anteil numeric not null check (bauzone_anteil between 0 and 1),
  e numeric not null, n numeric not null,
  lat double precision not null, lon double precision not null,
  primary key (ordner_id, egrid)
);
create index if not exists idx_wunsch_parzelle_ordner on public.wunsch_parzelle (ordner_id, flaeche desc);

alter table public.wunsch_ordner enable row level security;
alter table public.wunsch_parzelle enable row level security;
revoke all on public.wunsch_ordner, public.wunsch_parzelle from anon;
drop policy if exists wunsch_ordner_lesen on public.wunsch_ordner;
create policy wunsch_ordner_lesen on public.wunsch_ordner for select to authenticated using (true);
drop policy if exists wunsch_parzelle_lesen on public.wunsch_parzelle;
create policy wunsch_parzelle_lesen on public.wunsch_parzelle for select to authenticated using (true);
grant select on public.wunsch_ordner, public.wunsch_parzelle to authenticated;

insert into public.wunsch_ordner (id, name, kriterium, quelle, stand) values
  ('6a1f0c3e-5b7d-4e1a-9c2f-3d8b0e4a7f19', 'Über 3''000 m² · Sarnen und Nidwalden', 'über 3''000 m² in der Bauzone',
   'Sarnen, Stans, Stansstad, Hergiswil, Ennetbürgen und Buochs. Amtliche Vermessung beim Bund, ohne Baurechte; mindestens die Hälfte der Parzelle in der Bauzone.',
   '19. November 2026')
on conflict (id) do nothing;

